const stdout = ($input.first().json.stdout || '').trim();
if (!stdout) return [];

const lines = stdout.split('\n').map(v => v.trim()).filter(Boolean);
return lines.map(line => {
  try {
    return { json: JSON.parse(line) };
  } catch (e) {
    return { json: { kind: 'alert', reason: 'JSON parse edilemedi', raw: line } };
  }
});

parameters.command:
=FILEPATH="{{ $json.path }}";
FOLDER=$(dirname "$FILEPATH");
SENTRIX=$(basename "$FOLDER" | tr -d ' ');
METRICS_FILE=$(find "$FOLDER" -maxdepth 1 -type f -name 'Metrics*.txt' | grep -v old | head -1);

RAW_DATE=$(sed -n '2p' "$METRICS_FILE" | awk '{print $1}');
SCAN_DATE="";
if [ -n "$RAW_DATE" ]; then
  SCAN_DATE=$(python3 - <<'PY'
from datetime import datetime
raw = """$RAW_DATE""".strip()
for fmt in ("%m/%d/%Y", "%d.%m.%Y", "%Y-%m-%d"):
    try:
        print(datetime.strptime(raw, fmt).strftime("%Y-%m-%d"))
        break
    except Exception:
        pass
PY
)
fi

INSTRUMENT=$(grep -m1 '^name = ' "$FOLDER/Effective.cfg" 2>/dev/null | sed 's/^name = //g' | xargs)
DESCRIPTOR=$(grep -m1 'Descriptor:' "$FOLDER/${SENTRIX}_qc.txt" 2>/dev/null | sed 's/.*Descriptor:[[:space:]]*//' | awk -F'   ' '{print $1}' | xargs)
if [ -z "$DESCRIPTOR" ]; then
  DESCRIPTOR=$(grep -m1 '<Name>' "$FOLDER/${SENTRIX}.sdf" 2>/dev/null | sed 's/.*<Name>\(.*\)<\/Name>.*/\1/' | xargs)
fi

echo "{\"sentrix_id\":\"$SENTRIX\",\"scan_date\":\"$SCAN_DATE\",\"instrument_serial\":\"$INSTRUMENT\",\"descriptor\":\"$DESCRIPTOR\",\"metrics_path\":\"$METRICS_FILE\"}"

