return $input.all().map(item => {
  let parsed;
  try {
    parsed = JSON.parse(item.json.stdout || '{}');
  } catch (e) {
    parsed = {};
  }

  return {
    json: {
      sentrix_id: (parsed.sentrix_id || '').trim(),
      scan_date: (parsed.scan_date || '').trim(),
      instrument_serial: (parsed.instrument_serial || '').trim(),
      descriptor: (parsed.descriptor || '').trim(),
      metrics_path: (parsed.metrics_path || '').trim()
    }
  };
});

const baseUrl = (process.env.SUPABASE_URL || '').replace(/\/$/, '');
const serviceKey = process.env.SUPABASE_SERVICE_KEY || '';

if (!baseUrl || !serviceKey) {
  throw new Error('SUPABASE_URL ve SUPABASE_SERVICE_KEY environment variable olarak tanımlı değil.');
}

async function getOne(path) {
  const response = await this.helpers.request({
    method: 'GET',
    url: `${baseUrl}${path}`,
    headers: {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`
    },
    json: true
  });
  return Array.isArray(response) ? response[0] : null;
}

const out = [];

for (const item of $input.all()) {
  const row = item.json;

  if (!row.sentrix_id || !row.scan_date || !row.instrument_serial || !row.descriptor) {
    out.push({
      json: {
        action: 'alert',
        reason: 'Eksik alan var',
        ...row
      }
    });
    continue;
  }

  const instrument = await getOne.call(this, `/rest/v1/instruments?serial_number=eq.${encodeURIComponent(row.instrument_serial)}&select=uniqueref,care_site_ref`);
  if (!instrument) {
    out.push({
      json: {
        action: 'alert',
        reason: `Instrument bulunamadı: ${row.instrument_serial}`,
        ...row
      }
    });
    continue;
  }

  const chiptype = await getOne.call(this, `/rest/v1/kits_mapping?source_value=eq.${encodeURIComponent(row.descriptor)}&select=kits_ref,source_value`);
  if (!chiptype) {
    out.push({
      json: {
        action: 'alert',
        reason: `Kit mapping bulunamadı: ${row.descriptor}`,
        ...row
      }
    });
    continue;
  }

  const status = await getOne.call(this, `/rest/v1/concepts?concept_name=eq.Completed&select=uniqueref`);
  if (!status) {
    out.push({
      json: {
        action: 'alert',
        reason: 'Completed status concept bulunamadı',
        ...row
      }
    });
    continue;
  }

  out.push({
    json: {
      action: 'upsert',
      sentrix_id: row.sentrix_id,
      scan_date: row.scan_date,
      instrument_serial: row.instrument_serial,
      descriptor: row.descriptor,
      metrics_path: row.metrics_path,
      db_row: {
        sentrix_id: row.sentrix_id,
        scan_date: row.scan_date,
        status_concept_ref: status.uniqueref,
        instrument_ref: instrument.uniqueref,
        chiptype_ref: chiptype.kits_ref,
        care_site_ref: instrument.care_site_ref,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      }
    }
  });
}

return out;

const baseUrl = (process.env.SUPABASE_URL || '').replace(/\/$/, '');
const serviceKey = process.env.SUPABASE_SERVICE_KEY || '';

if (!baseUrl || !serviceKey) {
  throw new Error('SUPABASE_URL ve SUPABASE_SERVICE_KEY environment variable olarak tanımlı değil.');
}

const results = [];

for (const item of $input.all()) {
  const payload = item.json.db_row;

  const response = await this.helpers.request({
    method: 'POST',
    url: `${baseUrl}/rest/v1/scans?on_conflict=sentrix_id`,
    headers: {
      apikey: serviceKey,
      Authorization: `Bearer ${serviceKey}`,
      Prefer: 'resolution=merge-duplicates,return=representation'
    },
    body: payload,
    json: true
  });

  results.push({
    json: {
      status: 'ok',
      sentrix_id: item.json.sentrix_id,
      response
    }
  });
}

return results;
